 13	  const roadEnd=samples.at(-1)[0];
 14	  // A level service apron on the verified loading floor.
 15	  for(const point of [[45,0,43],[-10,0,30]])samples.push([samples.at(-1)[0]+distance(samples.at(-1).slice(1),point),...point]);
 16	  const length=samples.at(-1)[0];
 17	  function sample(s,lateral=0){
 18	    s=Math.max(0,Math.min(length,s));let lo=0,hi=samples.length-1;
 19	    while(hi-lo>1){const m=(lo+hi)>>1;if(samples[m][0]<=s)lo=m;else hi=m}
 20	    const a=samples[lo],b=samples[hi],t=(s-a[0])/(b[0]-a[0]||1);
 21	    const p=a.slice(1).map((v,i)=>mix(v,b[i+1],t));
 22	    const dx=b[1]-a[1],dz=b[3]-a[3],n=Math.hypot(dx,dz)||1;
 23	    // Negative Blender left-normal = outward, widened side of the bay.
 24	    p[0]-=dz/n*lateral;p[2]+=dx/n*lateral;return p;
 25	  }
 26	  const bays=design.passing_bays.map((b,i)=>({...b,index:i+1,s:b.station_m+offset,type:'PASSING_BAY'}));
 27	  const hubs=[{id:'CRUSHER',index:0,s:0,type:'CRUSHER'},...bays,{id:'LOADER',index:bays.length+1,s:length,type:'LOADER'}];
 28	  const stations=[0,length,...hubs.map(b=>b.s),...bays.flatMap(b=>[b.s-57.5,b.s-27.5,b.s+27.5,b.s+57.5])];
 29	  for(let s=18;s<length;s+=18)if(!stations.some(v=>Math.abs(v-s)<6))stations.push(s);
 30	  stations.sort((a,b)=>a-b);
 31	  const unique=stations.filter((s,i)=>!i||s-stations[i-1]>.001);
 32	  const nodes=[],edges=[],main=[],down=[],byId=new Map();
 33	  const node=(id,s,lateral=0,type='WAYPOINT',hub=null)=>{const n={id,s,position:sample(s,lateral),lateral,type,hub};nodes.push(n);byId.set(id,n);return id};
 34	  for(let i=0;i<unique.length;i++){
