 36	    const id=node('W'+i,s,0,hub?.type==='PASSING_BAY'?'WAYPOINT':hub?.type||'WAYPOINT',hub?.index??null);main.push(id);
 37	    const bay=bays.find(b=>Math.abs(s-b.s)<57.5-.001);
 38	    if(bay){const lateral=9.5*smooth((57.5-Math.abs(s-bay.s))/30);down.push(node('P'+i,s,lateral,hub?'PASSING_BAY':'WAYPOINT',hub?.index??null))}else down.push(id);
 39	  }
 40	  const edgeMap=new Map();
 41	  function chain(ids){return ids.slice(1).map((b,i)=>{const a=ids[i],key=a+':'+b;
 42	    if(edgeMap.has(key))return edgeMap.get(key);
 43	    const na=byId.get(a),nb=byId.get(b);const mid=(na.s+nb.s)/2;
 44	    const block=hubs.findIndex((h,j)=>j<hubs.length-1&&mid>=h.s&&mid<hubs[j+1].s);
 45	    const e={id:'E'+edges.length,from:a,to:b,length:distance(na.position,nb.position),isOccupied:false,direction:null,owner:null,block};edges.push(e);edgeMap.set(key,e.id);return e.id;
 46	  })}
 47	  const mainEdges=chain(main),downEdges=chain(down);
 48	  for(const h of hubs){h.mainNode=main[unique.findIndex(s=>Math.abs(s-h.s)<.001)];h.pocketNode=down[unique.findIndex(s=>Math.abs(s-h.s)<.001)];h.position=byId.get(h.pocketNode).position}
 49	  return {nodes,edges,hubs,bays,length,offset,roadEnd,samples,sample,downRoute:downEdges,upRoute:mainEdges.slice().reverse()};
 50	}
